export interface TemplateField {
  name: string;
  label: string;
  type: string;
  default: any;
  isSecret?: boolean;
}

export interface TemplateSchema {
  fields: TemplateField[];
}

export interface BuiltInTemplate {
  name: string;
  slug: string;
  version: string;
  description: string;
  author: string;
  previewImage: string;
  schema: TemplateSchema;
  files: Record<string, string>;
}

